begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('e1111111-1111-4111-8111-111111111111','membership-student@example.com'),
 ('e2222222-2222-4222-8222-222222222222','membership-guardian@example.com'),
 ('e3333333-3333-4333-8333-333333333333','membership-linked@example.com');
update public.profiles set role='guardian' where id='e2222222-2222-4222-8222-222222222222';
update public.profiles set role='student' where id in ('e1111111-1111-4111-8111-111111111111','e3333333-3333-4333-8333-333333333333');
select ok(not has_function_privilege('anon','public.cancel_pending_membership_order(text)','EXECUTE'),'anon cannot cancel orders');
select ok(has_function_privilege('authenticated','public.cancel_pending_membership_order(text)','EXECUTE'),'authenticated owner may cancel pending order');
select ok(not has_function_privilege('authenticated','public.claim_membership_payment(uuid,text,text,bigint)','EXECUTE'),'clients cannot claim financial approval');
select public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-cancel-first');
create temporary table first_order as select order_id from public.membership_payment_orders where idempotency_key='membership-cancel-first';
set local request.jwt.claim.sub='e2222222-2222-4222-8222-222222222222';
select throws_ok($$select public.cancel_pending_membership_order((select order_id from first_order))$$,'P0001','membership order not found','foreign owner cannot cancel');
set local request.jwt.claim.sub='e1111111-1111-4111-8111-111111111111';
select is((public.cancel_pending_membership_order((select order_id from first_order))->>'status'),'cancelled','unclaimed order cancellation is canonical');
select is((public.cancel_pending_membership_order((select order_id from first_order))->>'status'),'cancelled','duplicate cancellation is idempotent');
select is((public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-cancel-first')->>'status'),'failed','same key reports terminal order');
select throws_ok($$select public.claim_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from first_order),'cancelled_payment_fixture',9900)$$,'P0001','payment order is not confirmable','canceled order cannot activate');
select is((public.get_effective_membership('e1111111-1111-4111-8111-111111111111')->>'status'),'inactive','cancel does not grant membership');
select public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-claim-second');
create temporary table second_order as select order_id from public.membership_payment_orders where idempotency_key='membership-claim-second';
select public.claim_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from second_order),'membership_payment_fixture',9900);
select throws_ok($$select public.cancel_pending_membership_order((select order_id from second_order))$$,'P0001','membership order is not cancellable','claim and cancel share the order lock');
select is((public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-claim-second')->>'status'),'confirming','same key reports ongoing confirmation');
select public.confirm_toss_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from second_order),'membership_payment_fixture','{"status":"DONE"}'::jsonb);
create temporary table paid_period as select current_period_ends_at from public.memberships where user_id='e1111111-1111-4111-8111-111111111111';
select public.confirm_toss_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from second_order),'membership_payment_fixture','{"status":"DONE"}'::jsonb);
select is((select current_period_ends_at from public.memberships where user_id='e1111111-1111-4111-8111-111111111111'),(select current_period_ends_at from paid_period),'duplicate confirmation does not extend period');
select is((public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-claim-second')->>'status'),'confirmed','completed order survives active-membership gate');
select throws_ok($$select public.cancel_pending_membership_order((select order_id from second_order))$$,'P0001','membership order is not cancellable','checkout cancellation cannot revoke an approved membership');
select ok(public.has_effective_membership_entitlement('e1111111-1111-4111-8111-111111111111','ai-focus-coach'),'direct paid entitlement active');
update public.memberships set current_period_started_at=now()-interval '30 days',current_period_ends_at=now() where user_id='e1111111-1111-4111-8111-111111111111';
select ok(not public.has_effective_membership_entitlement('e1111111-1111-4111-8111-111111111111','ai-focus-coach'),'period equality expires access');
select is(public.get_effective_membership('e1111111-1111-4111-8111-111111111111')->>'status','inactive','expired status is projected inactive');
select is((public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-claim-second')->>'status'),'confirmed','old approval stays confirmed after membership expiry');
set local request.jwt.claim.sub='';
select public.create_membership_payment_order('e2222222-2222-4222-8222-222222222222','membership-family-fixture');
create temporary table guardian_order as select order_id from public.membership_payment_orders where idempotency_key='membership-family-fixture';
select public.claim_membership_payment('e2222222-2222-4222-8222-222222222222',(select order_id from guardian_order),'family_payment_fixture',12900);
select public.confirm_toss_membership_payment('e2222222-2222-4222-8222-222222222222',(select order_id from guardian_order),'family_payment_fixture','{"status":"DONE"}'::jsonb);
insert into public.family_links(student_user_id,guardian_user_id,issuer_user_id,issuer_role,status,linked_at) values('e3333333-3333-4333-8333-333333333333','e2222222-2222-4222-8222-222222222222','e2222222-2222-4222-8222-222222222222','guardian','active',now());
select ok(public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'linked student inherits enabled guardian entitlement');
select ok(public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-weekly-report'),'weekly report remains available through enabled family entitlement');
update public.membership_entitlements set enabled=false where user_id='e2222222-2222-4222-8222-222222222222' and feature_key='ai-focus-coach';
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'guardian disabled entitlement revokes inheritance');
select ok(not (public.get_effective_membership('e3333333-3333-4333-8333-333333333333')->'entitlements') ? 'ai-focus-coach','membership response matches entitlement denial');
update public.membership_entitlements set enabled=true,valid_until=now() where user_id='e2222222-2222-4222-8222-222222222222' and feature_key='ai-focus-coach';
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'expired guardian entitlement revokes inheritance');
update public.membership_entitlements set valid_until=now()+interval '1 day' where user_id='e2222222-2222-4222-8222-222222222222' and feature_key='ai-focus-coach';
select ok(public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'valid entitlement restores inherited feature');
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-guardian-summary'),'student cannot inherit guardian-only feature');
update public.memberships set status='inactive' where user_id='e2222222-2222-4222-8222-222222222222';
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'inactive guardian revokes access');
select is(public.get_effective_membership('e3333333-3333-4333-8333-333333333333')->>'status','inactive','inactive inherited membership is projected inactive');
update public.memberships set status='active',current_period_started_at=now()-interval '30 days',current_period_ends_at=now() where user_id='e2222222-2222-4222-8222-222222222222';
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'expired guardian revokes inherited access');
update public.memberships set current_period_started_at=now(),current_period_ends_at=now()+interval '30 days' where user_id='e2222222-2222-4222-8222-222222222222';
update public.family_links set status='disconnected',disconnected_at=now() where student_user_id='e3333333-3333-4333-8333-333333333333';
select ok(not public.has_effective_membership_entitlement('e3333333-3333-4333-8333-333333333333','ai-focus-coach'),'disconnect revokes inherited access');
select public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-needs-review');
select public.claim_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from public.membership_payment_orders where idempotency_key='membership-needs-review'),'legacy_bound_payment',9900);
select public.fail_membership_payment('e1111111-1111-4111-8111-111111111111',(select order_id from public.membership_payment_orders where idempotency_key='membership-needs-review'),'legacy_network_failure');
select is((public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-needs-review')->>'status'),'needs_review','unknown bound failure cannot become a new checkout');
select throws_ok($$select public.create_membership_payment_order('e1111111-1111-4111-8111-111111111111','membership-needs-review','family_seat')$$,'P0001','payment order ownership mismatch','same key cannot change product kind');
select * from finish();
rollback;
